-- Replace incomplete derived histology schedule rows with the detailed 18-lecture MBH plan from the SpaceWeb archive.
-- Old generated rows are retained but deactivated; the user's grade/credit row is untouched.
BEGIN;
WITH subject AS (
  SELECT id FROM public.subjects
  WHERE slug='histology' AND course_number=2 AND semester=3 AND is_active=true
  ORDER BY id LIMIT 1
),
deactivate_old AS (
  UPDATE public.curriculum_items ci
  SET is_active=false, updated_at=now()
  FROM subject s
  WHERE ci.subject_id=s.id
    AND ci.source='2026/2027 official histology schedule'
    AND ci.is_active=true
  RETURNING ci.id
),
seed(week_no,planned_date,lecture_title,topics,preparations) AS (
  VALUES
  (1,'2026-09-04','Введение в предмет. Цитология.',ARRAY['Введение в гистологию','Цитология','Гистологическая техника','Клеточная теория','Клетка и производные'],ARRAY['Видеофильм «Основы гистологической техники» (электронный вариант)','№1 Клетка животная (обозначить структуры ядра)','№2 Симпласт','№3 Межклеточное вещество (эластический хрящ)']),
  (2,'2026-09-11','Клетка. Структуры цитоплазмы. Ядро клетки. Деление клетки и его регуляция. Жизненный цикл клетки.',ARRAY['Цитоплазма','Ядро','Деление клетки','Жизненный цикл','Органеллы','Включения','ЭМ по цитологии'],ARRAY['№4 Аппарат Гольджи','№5 Липидные включения','№6 Включения гликогена']),
  (3,'2026-09-18','Основы общей эмбриологии. Строение половых клеток. Этапы и механизмы эмбриогенеза. Дифференцировка зародышевых листков.',ARRAY['Эмбриология','Половые клетки','Эмбриогенез','Зародышевые листки','Ядро','Митоз','Жизненный цикл'],ARRAY['№7 Ядро клетки','№8 Митоз','№9 Меченные ³H-тимидином ядра']),
  (4,'2026-09-25','Учение о тканях. Эпителии покровные и железистые.',ARRAY['Ткани','Эпителий покровный','Эпителий железистый','Половые клетки','Осевые органы','Зародышевые листки'],ARRAY['№10 Сперматозоиды','№11 Яйцеклетка млекопитающих','№12 Стадия зародышевых листков — первичная полоска','№13 Стадия осевых органов']),
  (5,'2026-10-02','Кровь и лимфа.',ARRAY['Кровь','Лимфа','Эпителий'],ARRAY['№14 Мезотелий','№15 Цилиндрический каёмчатый эпителий','№16 Многорядный реснитчатый эпителий','№17 Многослойный плоский эпителий','№19 Переходный эпителий']),
  (6,'2026-10-09','Соединительные ткани. Рыхлая волокнистая соединительная ткань. Плотная волокнистая соединительная ткань. Ткани со специальными свойствами.',ARRAY['Соединительная ткань','РВСТ','ПВСТ','Специальные свойства','Кровь','Гемограмма','Лейкоцитарная формула'],ARRAY['№20 Мезенхима','№21 Кровь человека. Подсчёт лейкоцитов в мазках крови']),
  (7,'2026-10-16','Скелетные ткани. Хрящевые ткани. Костные ткани.',ARRAY['Хрящ','Кость','РВСТ','Клетки соединительной ткани','ПВСТ'],ARRAY['№22 Рыхлая волокнистая соединительная ткань','№23 Фибробласты','№24 Эластические волокна и тканевые базофилы','№25 Ретикулярная ткань','№26 Жировая ткань','№27 Пигментная ткань','№28 Сухожилие']),
  (8,'2026-10-23','Мышечные ткани. Поперечно-полосатые. Гладкие.',ARRAY['Мышечная ткань','Поперечно-полосатая','Гладкая','Хрящ','Кость','Остеогенез'],ARRAY['№29 Гиалиновый хрящ','№30 Волокнистый хрящ','№31 Эластический хрящ','№32 Трубчатая кость','№33 Развитие кости из мезенхимы','№34 Развитие кости на месте хряща']),
  (9,'2026-10-30','Нервная ткань. Нейроглия, нейроциты, нервные волокна и окончания.',ARRAY['Нервная ткань','Нейроглия','Нейроциты','Нервные волокна','Окончания','Мышечные ткани','Саркомер'],ARRAY['№35 Гладкая мышечная ткань','№36 Поперечно-полосатая скелетная мышечная ткань','№37 Сердечная мышечная ткань']),
  (10,'2026-11-06','Частная гистология. Нервная система. Спинной мозг. Спинальный ганглий. Периферический нерв. Понятие о рефлекторной дуге.',ARRAY['Нервная система','Спинной мозг','Спинальный ганглий','Периферический нерв','Рефлекторная дуга','Нейроциты','Нейроглия','Нервные волокна'],ARRAY['№38 Нейрофибриллы в нейроцитах','№39 Тигроид в нейроците','№40 Астроцитарная глия','№41 Миелиновое нервное волокно']),
  (11,'2026-11-13','Строение коры больших полушарий головного мозга и мозжечка. Вегетативная нервная система. Симпатическая и парасимпатическая рефлекторные дуги.',ARRAY['Кора больших полушарий','Мозжечок','ВНС','Нервные окончания','Синапсы','Нервно-мышечное окончание'],ARRAY['№42 Тактильное тельце','№43 Пластинчатое тельце']),
  (12,'2026-11-20','Сенсорные системы. Анализаторы. Зрительный и обонятельный. Строение глаза. Сетчатка.',ARRAY['Зрительный анализатор','Обонятельный анализатор','Глаз','Сетчатка'],ARRAY['Повторение гистологических препаратов №1–43']),
  (13,'2026-11-27','Сенсорные системы. Анализаторы. Органы слуха, равновесия, вкуса. Внутреннее ухо. Строение Кортиева органа.',ARRAY['Слух','Равновесие','Вкус','Внутреннее ухо','Кортиев орган'],ARRAY['Повторение гистологических препаратов №1–43']),
  (14,'2026-12-04','Частная гистология. Сердечно-сосудистая система.',ARRAY['Сердечно-сосудистая система','Спинной мозг','Спинальный ганглий','Периферический нерв'],ARRAY['№44 Спинной мозг. Ядра и пучки','№45 Спинальный ганглий']),
  (15,'2026-12-11','Центральные и периферические звенья эндокринной системы.',ARRAY['Эндокринная система','Головной мозг','Кора','Мозжечок','ВНС'],ARRAY['№46 Периферический нерв','№47 Кора больших полушарий','№48 Кора мозжечка','№49 Грушевидный нейрон']),
  (16,'2026-12-18','Учение о кроветворении. Красный костный мозг. Миелопоэз.',ARRAY['Кроветворение','Красный костный мозг','Миелопоэз','Глаз','Сетчатка','Обоняние'],ARRAY['№50 Передняя часть (угол) глаза','№51 Задняя стенка глаза. Сетчатка','№52 Развитие глаза']),
  (17,'2026-12-25','Органы лимфоидного кроветворения и иммунологической защиты.',ARRAY['Лимфоидные органы','Иммунная защита','Слух','Равновесие','Вкус','Спиральный (Кортиев) орган'],ARRAY['№53 Вкусовая почка','№54 Улитка. Кортиев орган']),
  (18,'2027-01-18','Пищеварительный канал. Органы ротовой полости.',ARRAY['Пищеварительный канал','Ротовая полость'],ARRAY['Повторение гистологических препаратов №1–54'])
)
INSERT INTO public.curriculum_items
  (subject_id,course_number,semester,item_type,title,description,planned_date,order_index,is_required,is_active,source,metadata)
SELECT
  s.id,2,3,'lecture',
  'Лекция '||seed.week_no||'. '||seed.lecture_title,
  'Темы: '||array_to_string(seed.topics,', ')||E'\nПрепараты: '||array_to_string(seed.preparations,'; '),
  seed.planned_date::date,seed.week_no,true,true,
  'spaceweb:subject_plans/histology-semester3-2026-2027.json',
  jsonb_build_object(
    'legacy_plan_key','spaceweb:histology:week-'||lpad(seed.week_no::text,2,'0'),
    'week',seed.week_no,'lecture',seed.lecture_title,'practice',NULL,
    'topics',to_jsonb(seed.topics),'preparations',to_jsonb(seed.preparations),
    'source_file','data/subject_plans/histology-semester3-2026-2027.json',
    'source_plan','official department plan 2026/2027'
  )
FROM subject s CROSS JOIN seed
WHERE NOT EXISTS (
  SELECT 1 FROM public.curriculum_items existing
  WHERE existing.subject_id=s.id
    AND existing.metadata->>'legacy_plan_key'='spaceweb:histology:week-'||lpad(seed.week_no::text,2,'0')
);
COMMIT;
